export const sensoryDirectCases={};

// Frozen A-D key slots are retained while each legacy paired task becomes one focused question.
function addLegacy(number,keys,source,scenario,items){
 items.forEach(([question,key,...other],i)=>{
  other.splice(keys[i],0,key);
  sensoryDirectCases[`NP4-${number}-${i+1}`]={source,scenario,question,unsafeAnswer:i===4,
   choices:other.map(o=>o[0]),reasons:other.map(o=>o[1]),choiceSources:other.map(o=>o[2]??source)};
 });
}

